const documents={
'/docs':{title:'Documentation',intro:'What this release candidate does, how to use it, and where its evidence ends.',sections:[['1. Access your workspace','An administrator provisions an account. Sign in using your email and password. The session persists across refreshes until it expires or you revoke it. Public registration, email verification delivery, OAuth, and password reset delivery are not enabled in this release candidate.'],['2. Start a comparison','In Repositories, add a public GitHub owner/name. In New scan, choose the repository and baseline/proposed refs. You can also upload ZIP source archives or compare two OpenAPI 3.x JSON specifications. Only connect repositories you are authorized to analyze.'],['3. Read the result','A completed scan means the supported analysis finished; it does not mean your change is safe. Review severity, rule identifiers, evidence, confidence, recommended actions, and the stated limitations. Empty findings do not prove the absence of risk.'],['4. Keep or export evidence','Scan history is scoped to your organization. Open a completed scan to download its JSON or CSV report. Share exports carefully: they may contain source paths and evidence about your software.'],['5. Safe execution policy','This release candidate performs static analysis. It does not execute uploaded code or customer tests. Isolated runtime simulation, generated-test execution, and deployment blocking are unavailable. Predicted risks are never represented as executed tests.'],['6. Current limitations','Private GitHub credentials, webhook scans, scheduled scans, billing, external AI explanations, email alerts, and enterprise SSO are not enabled. Unsupported schema constructs and languages can limit findings. Review the per-scan limitations before relying on any report.'],['Support','For access, account recovery, deletion requests, and product questions, contact zevqlabs@gmail.com. Do not email credentials or confidential source code.']]},
'/security':{title:'Security & trust',intro:'A restricted release candidate with explicit boundaries. No security certification is claimed.',sections:[['Access and isolation','Authentication and organization-scoped permissions protect workspace data. Only authorized members should receive access. Public customer registration remains closed pending release approval.'],['Source handling','Analysis is read-only. Uploaded source is not executed in the API server. Do not submit regulated or highly confidential data until the deployment, retention, and contractual controls have been independently reviewed.'],['External services','Public repository scans contact GitHub. The core analyzer operates without an AI provider. External AI processing and live payments are disabled.'],['Sessions','Use a unique password and sign out on shared computers. Account settings provide session revocation. Report suspected unauthorized access promptly.'],['Disclosure and limitations','Contact zevqlabs@gmail.com to report a security concern. Include a description and reproduction steps without exposing personal data or credentials. A passing scan is not a security audit or a guarantee of production safety.']]},
'/pricing':{title:'Pricing',intro:'Commercial subscriptions are not available yet.',sections:[['Protected evaluation','This release candidate is for provisioned evaluation accounts. There is no checkout and no live payment collection. Access and limits are controlled by the administrator.'],['Future plans','Free, Starter, Team, Business, and Enterprise tiers are planned. Entitlements, prices, availability, support commitments, and applicable taxes have not been finalized.'],['Discuss your requirements','Tell us about your repository count, team size, analysis volume, and security requirements at zevqlabs@gmail.com. No paid subscription is created by contacting us.']]},
'/contact':{title:'Contact ZEVQ Labs',intro:'Questions, access requests, and product feedback.',sections:[['Email support','Write to zevqlabs@gmail.com with a short description of your request. For a scan issue, include the scan ID and an error description; do not include passwords, API tokens, or private code.'],['Request access','Public registration is closed. Email the support address to discuss access to the protected evaluation. Account provisioning is handled by an administrator.'],['Response expectations','There is no published support SLA during the release candidate. If a production system is affected, use your existing operational and incident-response processes.']]},
'/privacy':{title:'Privacy notice — release candidate',intro:'Draft operational notice. Legal review is pending; this is not a claim of regulatory compliance.',sections:[['Data processed','Account email addresses, password hashes, organization membership, session identifiers, repository references, scan metadata, findings, and audit events are processed to operate this workspace. Reports can contain source paths and analysis evidence.'],['Purpose and sharing','Data is used for account access, analysis, workspace history, and security operations. Hosting and GitHub services may process requests needed for these functions. External AI processing and live payments are disabled in this release candidate.'],['Retention and requests','Owners can delete organizations, including their stored workspace data. Account settings provide account export and account deletion after owned organizations have been removed. Final automatic retention periods are not established. Contact zevqlabs@gmail.com for questions before submitting sensitive data.'],['Cookies','An essential session cookie is used to keep you signed in. The workspace does not intentionally include advertising or analytics trackers. Signing out revokes your current session; logout-all revokes all account sessions.'],['Contact','Privacy questions can be sent to zevqlabs@gmail.com. Do not include credentials or sensitive source code in email.']]},
'/terms':{title:'Evaluation terms — draft',intro:'Restricted release candidate. Final commercial terms and legal review are pending.',sections:[['Authorized evaluation','Use only software and repositories you own or have permission to analyze. Do not upload malicious archives, stolen credentials, or content you are not authorized to process.'],['Analysis limitations','Results concern supported static checks and can include false positives and missed issues. Preflight cannot predict all failures and does not replace testing, security review, or engineering judgment. You remain responsible for deployment decisions.'],['Availability','This evaluation has no uptime guarantee, production support SLA, or finalized retention commitment. Features and interfaces may change. Keep independent copies of data you need.'],['Payments and launch','No live payments are collected. Public commercial launch requires additional implementation, testing, policy review, and owner approval.'],['Contact','For access and evaluation questions, contact zevqlabs@gmail.com.']]}}
