async function renderView(showLoading=true){clearTimeout(state.poll);const ticket=++state.render;const route=location.hash.slice(1)||'dashboard';const [view,id]=route.split('/');state.view=view;document.querySelector('.layout').classList.toggle('scan-theme',view==='new');const titles={dashboard:'Overview',repositories:'Repositories',new:'New scan',history:'Scan history',scan:'Analysis report',team:'Team members',audit:'Audit log',settings:'Settings'};document.getElementById('crumb').textContent=titles[view]||'Not found';document.querySelectorAll('.side-nav a').forEach(a=>{a.classList.toggle('active',a.dataset.view===view);if(a.dataset.view===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.getElementById('sidebar').classList.remove('open');document.querySelector('.mobile-menu').setAttribute('aria-expanded','false');const content=document.getElementById('content');if(showLoading)content.replaceChildren(el('div',{class:'loading',role:'status'},'Loading workspace…',el('div',{class:'skeleton'}),el('div',{class:'skeleton'}),el('div',{class:'skeleton'})));try{let page;if(!state.org&&view!=='settings')page=el('div',{},heading('Create your workspace','Create an organization to start analyzing changes.'),link('Create organization','/app#settings','button'));else{const views={dashboard,repositories,new:newScan,history,team,audit,settings};page=view==='scan'&&id?await scanDetail(id):views[view]?await views[view]():empty('Page not found','Choose a workspace page from the navigation.',link('Back to overview','/app#dashboard','button'))}if(ticket===state.render){content.replaceChildren(page);document.title=(titles[view]||'Workspace')+' — ZEVQ Preflight'}}catch(error){if(ticket===state.render)content.replaceChildren(heading('Unable to load this page',error.message),button('Try again',()=>renderView()),el('p',{class:'hint'},'Check your permissions and connection. ',link('Contact support','/contact')))}}
async function start(){const path=location.pathname.replace(/\/$/,'')||'/';if(path==='/app'){try{state.user=await api('/api/auth/me');const saved=preferences.get('zevq-org');state.org=state.user.organizations?.some(o=>String(o.id)===saved)?saved:state.user.organizations?.[0]?.id;showShell();window.addEventListener('hashchange',()=>renderView());await renderView()}catch(error){if(error.status===401){location.replace('/login')}else{publicShell(el('section',{class:'prose'},el('h1',{},'Unable to open your workspace'),el('p',{role:'alert'},error.message||'Please retry in a moment.'),button('Retry',()=>location.reload()),link('Back to sign in','/login','button secondary')))}}return}if(path==='/')landing();else if(path==='/login')loginPage();else if(documents[path])documentPage(path);else publicShell(el('article',{class:'prose'},el('div',{class:'eyebrow'},'404 / Page not found'),el('h1',{},'This route is unavailable.'),el('p',{},'The page may have moved, or the address may be incorrect.'),link('Return home','/','button')))}
